INSERT INTO equipos.recurso_software (id_recurso, id_software) SELECT r.id_recurso, s.id_software FROM equipos.recursos_ct r JOIN equipos.carro c ON c.id_carro = r.id_carro JOIN equipos.software s ON s.nombre_software IN (N'Qt Creator', N'Visual Studio Code', N'Microsoft Office') WHERE c.nombre_carro = N'C4';
INSERT INTO equipos.recurso_software (id_recurso, id_software) SELECT r.id_recurso, s.id_software FROM equipos.recursos_ct r JOIN equipos.carro c ON c.id_carro = r.id_carro JOIN equipos.software s ON s.nombre_software = N'SQL Server 2005' WHERE c.nombre_carro = N'C4' AND r.numero_equipo <= 5;
INSERT INTO equipos.recurso_software (id_recurso, id_software) SELECT r.id_recurso, s.id_software FROM equipos.recursos_ct r JOIN equipos.carro c ON c.id_carro = r.id_carro JOIN equipos.software s ON s.nombre_software = N'DBeaver' WHERE c.nombre_carro = N'C4' AND r.numero_equipo > 5;
INSERT INTO equipos.recurso_software (id_recurso, id_software) SELECT r.id_recurso, s.id_software FROM equipos.recursos_ct r JOIN equipos.carro c ON c.id_carro = r.id_carro JOIN equipos.software s ON s.nombre_software IN (N'AutoCAD', N'Visual Studio Code', N'Microsoft Office') WHERE c.nombre_carro = N'C5';
