UPDATE tienda.producto_buffet SET id_categoria_producto = (SELECT id_categoria_producto FROM tienda.categoria_producto WHERE nombre_categoria = N'Comida') WHERE nombre_producto IN (N'Alfajor de dulce de leche', N'Sándwich de miga');
UPDATE tienda.producto_buffet SET id_categoria_producto = (SELECT id_categoria_producto FROM tienda.categoria_producto WHERE nombre_categoria = N'Bebida') WHERE nombre_producto = N'Jugo en caja';
